#!/usr/bin/env bash
# B series, Figs 4, 6, 7 (2026-10-21, eric-mimicc-0-1), completing the b set begun by
# run_B_luc3d_build.sh (Figs 1, 2, 3, 5). Same inputs and env as that build: the b link set
# (x7's links + overrides, all required), plus one more override:
#   fig6_detections_proofread_notail -> fig6_detections_proofread_notail_nopy.json (Fig 4C),
#   regenerated by fig4_detections.py with its NumPy triage block deleted; its per-session,
#   by-difficulty and by-animals data are identical to the August file.
# fig6_detections.json (Figs 4 animal-count / strata / IDF1 / occlusion) stays the August
# file, as placed (Eric, 2026-10-21). Writes only figures/fig{4,6,7}b + data/fig{4,6,7}b.
set -uo pipefail
R=/root/vast/eric/sleap-3d-gui/scratch/repos/lucid; F=$R/figs; cd $F
L=out/md56_logs; O=out; FPY=.venv/bin/python
fail() { echo "B467 FAILED: $*"; exit 1; }
for n in 4 6 7; do { [ -e figures/fig${n}b ] || [ -e data/fig${n}b ]; } && fail "figures/fig${n}b or data/fig${n}b exists"; done

# the Fig 4C override: repoint its b link, record it in B_links.tsv
[ -s $O/fig6_detections_proofread_notail_nopy.json ] || fail "missing the regenerated Fig 4C deposit"
ln -sfn fig6_detections_proofread_notail_nopy.json $O/fig6_detections_proofread_notail_b.json
$FPY - <<'PY' || fail "B_links update"
p = "out/md56_logs/B_links.tsv"
rows = [l.rstrip("\n").split("\t") for l in open(p)]
for r in rows:
    if r[0] == "fig6_detections_proofread_notail.json":
        r[1], r[2] = "fig6_detections_proofread_notail_nopy.json", "override"
open(p, "w").writelines("\t".join(r) + "\n" for r in rows)
PY

export FIG_TAG=b FIG_RENDER_REQUIRE=1 FIG_APP_OUT=out/b_app
export FIG6F_NOEVICT=stale0_dist25 SIGN_TIES_EXCLUDED=1 FIG5G_PERDIR=1 F3_TRUE_MEDIAN=1 FIG3F_CLEAN=1 \
       FIG3F_CLEAN_TAG=_j17 FIG6_SDANNCE_AGG=$F/fig10-bench/results_v105/agg
export FIG_VARIANT=b FIG_VARIANT_LOG=$PWD/$L/B467_loads.tsv
export FIG_VARIANT_REQUIRE=$(cut -f1 $L/B_links.tsv | paste -sd, -)
rm -f $L/B467_loads.tsv
# Fig 6 f is panels/fig6slapstale_reduction.py (not in make_figures' glob); it writes the
# axes json fig6_09 copies, so it runs first (as run_X7_build.sh).
mkdir -p figures/fig6b
$FPY panels/fig6slapstale_reduction.py > $L/B_fig6f.log 2>&1 || fail "fig6 f"
for n in 4 6 7; do
  $FPY make_figures.py $n > $L/B_fig$n.log 2>&1; E=$?
  NF=$(grep -c "    ! " $L/B_fig$n.log || true)
  echo "fig${n}b exit=$E failed_panels=$NF $(tail -n1 $L/B_fig$n.log)"
  [ $E -eq 0 ] && [ "$NF" = 0 ] || fail "fig$n (see $L/B_fig$n.log)"
done
# the unplaced non-variant within-vs-cross panel, as every b / c / x7 build drops it
rm -f figures/fig6b/fig6ba_within_vs_cross.pdf figures/fig6b/fig6ba_within_vs_cross.png data/fig6b/fig6a_within_vs_cross.csv
echo "--- loads that did NOT come from a b link:"; awk -F'\t' '$3 !~ /_b\./' $L/B467_loads.tsv | cut -f2,3 | sort | uniq -c

for n in 4 6 7; do echo "=== data/fig${n}b vs data/fig$n"; for f in data/fig${n}b/*.csv; do
  b=$(basename $f); [ -e data/fig$n/$b ] || { echo "NEW $b"; continue; }; cmp -s $f data/fig$n/$b || echo "DIFF $b"; done; done
git -C $R status --short -- figs/figures/fig4 figs/figures/fig6 figs/figures/fig7 \
    figs/data/fig4 figs/data/fig6 figs/data/fig7 | grep . && fail "main figures changed"
echo "B467 BUILD DONE"
